bool KTWReferenceUI::RogueAction(AKTWRogueRun* R,const FString& Id){
 if(Id==TEXT("Help")){if(auto* S=UKTWSession::Get(R))S->Action(TEXT("How"));return true;}if(Id==TEXT("Pause")){if(auto* S=UKTWSession::Get(R)){S->PausedMenu=true;UGameplayStatics::SetGamePaused(R->GetWorld(),true);}return true;}
 if(Id.StartsWith(TEXT("Pick"))&&R->Phase==EKTWRoguePhase::Draft){const int Card=FCString::Atoi(*Id.Mid(4));if(R->Choices.Contains(Card))Picks.FindOrAdd(R)=Card;return true;}
 if(Id==TEXT("RefreshRules")){if(R->RefreshRules())Picks.Remove(R);return true;}if(Id==TEXT("ConfirmRule")){const int* Pick=Picks.Find(R);if(Pick&&R->Choices.Contains(*Pick)){const int Value=*Pick;Picks.Remove(R);R->Action(FString::Printf(TEXT("Card%d"),Value));}return true;}
 if(Id.StartsWith(TEXT("SetSpeed"))){const float Values[]={.5f,1,2};R->Speed=Values[FMath::Clamp(FCString::Atoi(*Id.Right(1)),0,2)];UGameplayStatics::SetGlobalTimeDilation(R->GetWorld(),R->Speed);return true;}
 if(Id==TEXT("SelectAll")||Id.StartsWith(TEXT("Select"))){const int Type=Id==TEXT("SelectAll")?-1:FCString::Atoi(*Id.Mid(6));R->Selected.Empty();for(auto U:R->Units)if(U&&U->Alive&&U->Team==0&&(Type<0||U->Type==Type))R->Selected.Add(U);return true;}return false;
}
