bool KTWReferenceUI::StreetClick(AKTWHoloHUD* H,float X,float Y){
 auto* PC=Cast<AKTWPrototypeController>(H->GetOwningPlayerController());auto* M=AKTWMatch::Find(H->GetWorld());if(!PC||!M)return false;const auto* Buttons=StreetButtons.Find(H);if(!Buttons)return false;for(const auto& B:*Buttons)if(Inside(B.Rect,X,Y)){if(!B.Enabled)return true;const FString Id=B.Id;
  if(Id==TEXT("Help")){if(auto* S=UKTWSession::Get(H))S->Action(TEXT("How"));}
  else if(Id==TEXT("Pause")){if(auto* S=UKTWSession::Get(H)){S->PausedMenu=true;UGameplayStatics::SetGamePaused(H->GetWorld(),true);}}
  else if(Id==TEXT("View")){if(auto* Cam=Cast<AKTWCameraPawn>(PC->GetPawn())){const bool Enter=!Cam->bStreetView;Cam->SetStreetView(Enter);if(Enter&&(PC->SelectedBoss||PC->SelectedUnit))Cam->FrameSelection(true);}}
  else if(Id==TEXT("Map")){if(auto* C=Cast<AKTWCameraPawn>(PC->GetPawn()))C->ShowMap();}
  else if(Id==TEXT("Start"))M->StartBattle();
  else if(Id.StartsWith(TEXT("Lane")))PC->SelectLaneKey(Id.EndsWith(TEXT("0"))?EKeys::Z:Id.EndsWith(TEXT("1"))?EKeys::X:EKeys::C);
  else if(Id.StartsWith(TEXT("Recruit"))){const int Role=FCString::Atoi(*Id.Right(1));if(Role<4)M->Purchase(0,EKTWRole(Role),M->SelectedLane);else M->OpenBox(0,M->SelectedLane);}
  else if(Id.StartsWith(TEXT("Command"))){const int Command=FCString::Atoi(*Id.Right(1));auto* Boss=PC->SelectedBoss.Get();AKTWTestUnit* Target=nullptr;float Best=-MAX_flt;for(TActorIterator<AKTWTestUnit>I(H->GetWorld());I;++I)if(I->Faction==0&&I->Health>0){if(Command==0&&!I->bRunner)continue;auto* Cargo=I->FindComponentByClass<UKTWGoldCarrier>();const float Score=(Command==0&&Cargo?Cargo->Carried*1000.f:0)-(Boss?FVector::Dist2D(Boss->GetActorLocation(),I->GetActorLocation()):0);if(Score>Best){Best=Score;Target=*I;}}
   if(Boss){if(Command==0||Command==2){if(Target)Boss->IssueTask(Command==0?EKTWBossTask::Escort:EKTWBossTask::Follow,Target->GetActorLocation(),Target);}else if(Command==3)Boss->IssueTask(EKTWBossTask::Return,FVector::ZeroVector,nullptr);else if(Command==1){if(Boss->IssueTask(EKTWBossTask::Sit,Boss->GetActorLocation(),nullptr))Boss->bHoldPosition=true;}else Boss->IssueTask(EKTWBossTask::Sit,UKTWGoldCarrier::VaultPosition(1,M->SelectedLane),nullptr);}
   for(auto U:PC->SelectedUnits)if(IsValid(U)&&U->Health>0){if(Command==1)U->IssueOrder(EKTWUnitOrder::Defend,U->GetActorLocation());else if(Command==3)U->IssueOrder(EKTWUnitOrder::Retreat,AKTWStreetDirector::BasePosition(0));else if(Command==4){U->Lane=M->SelectedLane;if(auto* C=U->FindComponentByClass<UKTWGoldCarrier>())C->RequestRaid();}else if(Target&&Target!=U)U->IssueOrder(EKTWUnitOrder::Escort,Target->GetActorLocation(),Target);}
  }return true;
 }return false;
}
